/**
 * Addressing modes per CPU target, with the opcode byte and instruction length
 * of each form.
 *
 * GENERATED - do not edit by hand. Every entry was probed from 64tass itself:
 * each candidate operand syntax was assembled, and the mode was read back from
 * the listing's monitor column (the assembler's own disassembly) rather than
 * assumed from the syntax fed in. That is what distinguishes `lda $34,y`
 * (which encodes absolute,y) from a real zeropage,y form, and a relative branch
 * from an absolute jump. See test/integration/addressing.test.ts, which checks
 * this table back against the assembler.
 *
 * Each target is probed under the flag that actually selects it (see CPU_FLAG in
 * test/helpers/compiler.ts) - notably `6502` is --m65xx and `6502i` is --m6502,
 * not the other way round.
 *
 * Operand patterns use `$hh` for one byte, `$hhhh` for two, `$hhhhhh` for three,
 * `<label>` for a relative branch target and `<bit>` for a bit number.
 */

/** [operand pattern, opcode byte, instruction length in bytes] */
export type AddressingMode = readonly [pattern: string, opcode: number, length: number];

